insert into public.dialogue_lines (dialogue_id, locale, line_order, content, line_format) select dialogues.id, lines.locale, lines.line_order, lines.content, lines.line_format from jsonb_to_recordset($seed$[{"dialogue_key":"adjectives_mastery_adjectives_mastery_q01_adjectives_s03","locale":"he","line_order":0,"content":"מצויין. למדנו על Dirty ו Clean! הפסל היה מלוכלך ועכשיו הוא נקי!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q01_adjectives_s03_copy","locale":"he","line_order":0,"content":"אלופים! בלי המדורה יכל להיות מאוד Dark... שנדליק אותה יהיה Bright!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q01_adjectives_s09","locale":"he","line_order":0,"content":"כל הכבוד! למדתם 6 שמות תואר חדשים!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q01_adjectives_start","locale":"he","line_order":0,"content":"ברוכים השבים -  Welcome Back!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q02_boo_radcliff_s06","locale":"he","line_order":0,"content":"וואו חברים! אני חושב שאתה סווווופר קרובים להיות מאסטרים של Adjectives!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q02_boo_radcliff_start","locale":"he","line_order":0,"content":"שלוםםםםםםםם גיבור!\nנשלחת אליי להיות מאסטר של שמות תואר?\nאין בעיה!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q03_mountain_guide_s06","locale":"he","line_order":0,"content":"וואו!","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q03_mountain_guide_start","locale":"he","line_order":0,"content":"היי חבר'ה! שמעתי אתם רוצים ללמוד משהו חדש....","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q04_new_quest_start","locale":"he","line_order":0,"content":"היי חזרתם! ","line_format":"plain_text"},{"dialogue_key":"adjectives_mastery_adjectives_mastery_q04_new_quest_turn_in","locale":"he","line_order":0,"content":"הפכתם למאסטרים לפניי.... אני חייבת לרוץ ללמוד!","line_format":"plain_text"}]$seed$::jsonb) as lines(dialogue_key text, locale text, line_order integer, content text, line_format text) join public.dialogues on dialogues.key = lines.dialogue_key on conflict (dialogue_id, locale, line_order) do update set content = excluded.content, line_format = excluded.line_format;
